	}

	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+john.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/customers/"+john.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("deleted customer: %s", r)
	}
}

