func TestDeleteAndRestoreCustomers(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	john := e.CreateCustomer(e.Acme, "John", "john@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": p.ID}, &sub)
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, nil)

	e.Clock.Advance(time.Minute)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	gone := []struct {
		method, path string
		body         any
	}{
		{"GET", "/v1/customers/" + jane.ID, nil},
		{"PATCH", "/v1/customers/" + jane.ID, map[string]string{"name": "Changed"}},
		{"DELETE", "/v1/customers/" + jane.ID, nil},
		{"POST", "/v1/invoices", map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 100}}}},
		{"POST", "/v1/subscriptions", map[string]any{"customer_id": jane.ID, "plan_id": p.ID}},
	}
	for _, g := range gone {
		if r := e.Do(g.method, g.path, e.Acme.Key, g.body); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
			t.Fatalf("%s %s: %s", g.method, g.path, r)
		}
	}
	var page struct {
		Items []store.Customer `json:"items"`
	}
	for _, q := range []string{"", "?q=jane", "?email=JANE@example.com"} {
		page.Items = nil
		e.MustDo(http.StatusOK, "GET", "/v1/customers"+q, e.Acme.Key, nil, &page)
		if len(page.Items) != map[bool]int{true: 1, false: 0}[q == ""] || (q == "" && page.Items[0].ID != john.ID) {
			t.Fatalf("GET /v1/customers%s = %+v", q, page.Items)
		}
	}
	r := e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil)
	if rows, err := csv.NewReader(strings.NewReader(string(r.Body))).ReadAll(); err != nil || len(rows) != 2 || rows[1][0] != john.ID {
		t.Fatalf("csv = %v, %v", rows, err)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.deleted", e.Acme.Key, nil, &struct {
		Items []store.Event `json:"items"`
